//! Wolfram golden replay: baffled-piston radiation impedance.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `fixtures/piston_golden.wls` under Wolfram Engine 15.0.0) evaluates the
//! normalized resistance R(ka) = 1 - J1(2 ka)/ka and reactance
//! X(ka) = H1(2 ka)/ka with Wolfram's independent `BesselJ`/`StruveH`
//! against the crate's numerical Struve quadrature (and the small-ka Taylor
//! branch). Frequencies ride along as fixture inputs so both sides form
//! ka = 2 Pi f a/c from identical decimals.

use num_complex::Complex64;
use serde::Deserialize;
use sonium_sim_speaker_modeling::{
    AcousticMedium, baffled_piston_directivity, baffled_piston_far_field_pressure,
    baffled_piston_mechanical_radiation_impedance,
};
use std::collections::HashMap;
use std::f64::consts::PI;

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");
const RADIUS_M: f64 = 0.1;

#[derive(Debug, Deserialize)]
struct Entry {
    value: String,
    exact: String,
}

#[derive(Debug, Deserialize)]
struct Meta {
    engine: String,
    protocol: String,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    meta: Meta,
    values: HashMap<String, Entry>,
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Wolfram piston fixture");
    assert!(
        fixture.meta.engine.contains("Wolfram Engine"),
        "fixture must record its Wolfram provenance"
    );
    assert_eq!(fixture.meta.protocol, "audit-oracle-hermetic-v1");
    fixture
}

fn golden(fixture: &Fixture, name: &str) -> f64 {
    fixture.values[name]
        .value
        .parse()
        .expect("golden is a decimal")
}

#[test]
fn baffled_piston_impedance_matches_wolfram() {
    let fixture = parse_fixture();
    assert!(
        fixture.values["R_ka_1."].exact.contains("BesselJ"),
        "resistance golden must document the Bessel formulation"
    );
    assert!(
        fixture.values["X_ka_1."].exact.contains("StruveH"),
        "reactance golden must document the Struve formulation"
    );
    let medium = AcousticMedium::standard_air();
    let scale = medium.density_kg_per_m3 * medium.sound_speed_m_per_s * PI * RADIUS_M * RADIUS_M;
    for ka_tag in ["0.0001", "0.5", "1.", "2.", "5."] {
        let frequency = golden(&fixture, &format!("f_ka_{ka_tag}"));
        let impedance = baffled_piston_mechanical_radiation_impedance(RADIUS_M, frequency, medium)
            .expect("fixture frequencies are positive");
        let expected_r = golden(&fixture, &format!("R_ka_{ka_tag}"));
        let expected_x = golden(&fixture, &format!("X_ka_{ka_tag}"));
        assert!(
            (impedance.re / scale - expected_r).abs() < 1e-9,
            "ka={ka_tag}: R Rust {} vs Wolfram {expected_r}",
            impedance.re / scale
        );
        assert!(
            (impedance.im / scale - expected_x).abs() < 1e-9,
            "ka={ka_tag}: X Rust {} vs Wolfram {expected_x}",
            impedance.im / scale
        );
    }
}

#[test]
fn piston_directivity_matches_wolfram() {
    let fixture = parse_fixture();
    let frequency = golden(&fixture, "f_ka_1.");
    let medium = AcousticMedium::standard_air();
    for (angle, name) in [
        (0.0, "dir_0"),
        (30.0, "dir_30"),
        (60.0, "dir_60"),
        (90.0, "dir_90"),
    ] {
        let actual = baffled_piston_directivity(RADIUS_M, frequency, angle, medium)
            .expect("directivity angle in range");
        let expected = golden(&fixture, name);
        assert!(
            (actual - expected).abs() < 1e-12,
            "D({angle} deg): Rust {actual} vs Wolfram {expected}"
        );
    }
}

#[test]
fn piston_far_field_pressure_matches_wolfram() {
    let fixture = parse_fixture();
    let frequency = golden(&fixture, "f_ka_1.");
    let medium = AcousticMedium::standard_air();
    let velocity = Complex64::new(0.03, -0.01);
    let actual =
        baffled_piston_far_field_pressure(RADIUS_M, frequency, velocity, 2.3, 37.0, medium)
            .expect("far-field inputs are valid");
    // Complex phasor: phase, normalization, and axis conventions all ride
    // on both components, so compare each against its own golden.
    let expected_re = golden(&fixture, "ff_re");
    let expected_im = golden(&fixture, "ff_im");
    let scale = actual.norm().max(expected_re.hypot(expected_im)).max(1e-30);
    assert!(
        (actual.re - expected_re).abs() / scale < 1e-9,
        "Re(p): Rust {} vs Wolfram {expected_re}",
        actual.re
    );
    assert!(
        (actual.im - expected_im).abs() / scale < 1e-9,
        "Im(p): Rust {} vs Wolfram {expected_im}",
        actual.im
    );
}

#[test]
fn full_mechanical_impedance_matches_wolfram() {
    let fixture = parse_fixture();
    let frequency = golden(&fixture, "f_ka_1.");
    let impedance = baffled_piston_mechanical_radiation_impedance(
        RADIUS_M,
        frequency,
        AcousticMedium::standard_air(),
    )
    .expect("ka=1 frequency is positive");
    // The rho-c-A scaling is pinned absolutely here, not just normalized.
    let expected_re = golden(&fixture, "Z_full_re");
    let expected_im = golden(&fixture, "Z_full_im");
    assert!(
        (impedance.re - expected_re).abs() / expected_re.abs() < 1e-9,
        "Re(Z): Rust {} vs Wolfram {expected_re}",
        impedance.re
    );
    assert!(
        (impedance.im - expected_im).abs() / expected_im.abs() < 1e-9,
        "Im(Z): Rust {} vs Wolfram {expected_im}",
        impedance.im
    );
}
